package com.smartinternship.controller; import com.smartinternship.service.AiRecommendationService; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/recommendations") public class RecommendationController { private final AiRecommendationService s; public RecommendationController(AiRecommendationService s){this.s=s;} @GetMapping("/student/{id}") public List<Map<String,Object>> recommend(@PathVariable Long id){return s.recommend(id);} }